// Expand each uploaded file into its own item with the binary under a single key 'data'
const results = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    results.push({
      json: { ...item.json, sourceBinaryKey: key, fileName: bin[key].fileName || key },
      binary: { data: bin[key] },
    });
  }
}
return results;

const results = [];

for (const item of $input.all()) {

  const appts = (item.json.output && item.json.output.appointments) || [];

  // Get doctors from the input
  const doctors = item.json.doctors || [];

  for (const a of appts) {

    const rawDate = String(a.date || '').trim();
    const rawTime = String(a.time || '').trim();

    // Find the doctor using doctor_id
    const doctor = doctors.find(
      d => String(d.doctor_id).trim() === String(a.doctor_id).trim()
    );

    // Try 12-hour format
    let dt = DateTime.fromFormat(
      rawDate + ' ' + rawTime,
      'yyyy-M-d h:mm a',
      { zone: 'Asia/Manila' }
    );

    // Try 24-hour format
    if (!dt.isValid) {
      dt = DateTime.fromFormat(
        rawDate + ' ' + rawTime,
        'yyyy-M-d H:mm',
        { zone: 'Asia/Manila' }
      );
    }

    // Skip invalid date/time
    if (!dt.isValid) continue;

    const formattedDate = dt.toFormat('MMMM d, yyyy');
    const formattedTime = dt.toFormat('h:mm a');

    // Doctor information
    const doctorName = doctor?.name || 'N/A';
    const specialization = doctor?.specialization || 'N/A';

    // Build appointment message
    const appointmentDetails = `Patient ID: ${a.patient_id || 'N/A'}
Doctor: ${doctorName}
Specialization: ${specialization}
Date: ${formattedDate}
Time: ${formattedTime}
Purpose: ${a.purpose || 'N/A'}
Status: ${a.status || 'N/A'}

📍 Clinic: ${a.clinic_id || 'N/A'}`;

    results.push({
      json: {
        ...a,

        // Add doctor information
        doctor_name: doctorName,
        specialization: specialization,

        // Calendar values
        start_iso: dt.toISO(),
        end_iso: dt.plus({ hours: 1 }).toISO(),

        // Gmail message
        appointment_details: appointmentDetails
      }
    });
  }
}

return results;
